    {
      "name": "연결 기준",
      "desc": "회사와 지배하는 자회사의 재무 정보를 하나로 합친 기준입니다. 내부 거래는 제거합니다."
    },
    {
      "name": "방산",
      "desc": "군사 장비·무기와 관련 기술·서비스를 공급하는 방위산업입니다."
    },
    {
      "name": "커넥터",
      "desc": "전기·전자 부품 사이에 전력이나 신호를 연결하는 접속 부품입니다."
    },
    {
      "name": "납품",
      "desc": "주문받은 제품을 정해진 조건에 맞춰 고객에게 공급하는 것입니다."
    },
    {
      "name": "연구개발",
      "desc": "새 제품·기술을 연구하고 실제 사용할 수 있도록 개발하는 활동입니다. 지출이 곧바로 매출이나 성공을 뜻하지는 않습니다."
    },
    {
      "name": "고주파",
      "desc": "미용 의료기기 문맥에서는 전자기 에너지로 조직에 열을 전달하는 방식을 뜻합니다."
    },
    {
      "name": "RF",
      "desc": "무선통신 등에 쓰는 고주파 신호를 뜻합니다."
    },
    {
      "name": "안테나",
      "desc": "전자파 신호를 보내거나 받는 장치입니다."
    },
    {
      "name": "반기",
      "desc": "6개월 기간입니다. 반기 누적 실적은 한 분기의 3개월 실적과 다릅니다."
    }
  ],
